/*
 * Item and ability metadata catalog (rs3_catalog.bin).
 *
 * Our own interchange format, generated by tools/generate_catalog.py from the
 * local game cache. Every word is little endian:
 *
 *   header     88 bytes: magic, format, counts, client SHA-256, body SHA-256;
 *   items      sorted by item ID, 40 bytes each;
 *   abilities  sorted by struct ID, 48 bytes each;
 *   strings    NUL-terminated UTF-8 names; offsets are relative to the table.
 *
 * The loader validates every bound before publishing the backing buffer. The
 * checksum verifies integrity, not trust in an externally supplied file.
 */
#ifndef RS3_CATALOG_H
#define RS3_CATALOG_H

#include <stddef.h>
#include <stdint.h>
#include <wchar.h>

#define CATALOG_FILE_NAME      L"rs3_catalog.bin"
#define CATALOG_MAGIC          "RS3CAT1"
#define CATALOG_MAGIC_BYTES    8u
#define CATALOG_FORMAT_VERSION 1u
#define CATALOG_SHA256_BYTES   32u
#define CATALOG_NAME_CAPACITY  128u
#define CATALOG_ERROR_CAPACITY 128u

/* Header layout. */
#define CATALOG_HEADER_BYTES         88u
#define CATALOG_HEADER_FORMAT        8u
#define CATALOG_HEADER_ITEM_COUNT    12u
#define CATALOG_HEADER_ABILITY_COUNT 16u
#define CATALOG_HEADER_STRINGS_SIZE  20u
#define CATALOG_HEADER_CLIENT_SHA256 24u
#define CATALOG_HEADER_BODY_SHA256   56u

/* Item record layout: ten 32-bit words. */
#define CATALOG_ITEM_RECORD_BYTES      40u
#define CATALOG_ITEM_ID                0u
#define CATALOG_ITEM_NAME_OFFSET       4u
#define CATALOG_ITEM_FAMILY_ID         8u
#define CATALOG_ITEM_DOSES             12u
#define CATALOG_ITEM_NEXT_DOSE_ITEM_ID 16u
#define CATALOG_ITEM_EQUIP_SLOT        20u
#define CATALOG_ITEM_COMBAT_STYLE      24u
#define CATALOG_ITEM_EQUIPMENT_FLAGS   28u
#define CATALOG_ITEM_EFFECT_FLAGS      32u
#define CATALOG_ITEM_BASE_HEAL         36u

/* Ability record layout: twelve 32-bit words. */
#define CATALOG_ABILITY_RECORD_BYTES           48u
#define CATALOG_ABILITY_STRUCT_ID              0u
#define CATALOG_ABILITY_NAME_OFFSET            4u
#define CATALOG_ABILITY_START_VAR              8u
#define CATALOG_ABILITY_END_VAR                12u
#define CATALOG_ABILITY_BASE_COOLDOWN_MS       16u
#define CATALOG_ABILITY_REQUIREMENTS           20u
#define CATALOG_ABILITY_COMBAT_STYLE           24u
#define CATALOG_ABILITY_TIMER_SOURCE           28u
#define CATALOG_ABILITY_LEVEL_REQUIREMENT      32u
#define CATALOG_ABILITY_ADRENALINE_REQUIREMENT 36u
#define CATALOG_ABILITY_NATIVE_ID              40u
#define CATALOG_ABILITY_DEFINITION_FLAGS       44u

/* Bits of the ability definition flags word. */
#define CATALOG_ABILITY_IN_BOOK             1u
#define CATALOG_ABILITY_BASE_COOLDOWN_KNOWN 2u

/** A validated catalog and views into its backing buffer. */
typedef struct item_catalog
{
    unsigned char *data; /**< Owned backing buffer, or NULL. */
    size_t size;
    uint32_t status; /**< enum rs3_status. */
    uint32_t item_count;
    uint32_t ability_count;
    uint32_t strings_size;
    const unsigned char *item_records;
    const unsigned char *ability_records;
    const char *strings;
    char error_message[CATALOG_ERROR_CAPACITY];
} item_catalog;

/** Decoded item record. */
typedef struct catalog_item_definition
{
    uint32_t item_id;
    uint32_t name_offset;
    uint32_t family_id;
    int32_t doses;
    int32_t next_dose_item_id;
    int32_t equip_slot;
    uint32_t combat_style;
    uint32_t equipment_flags;
    uint32_t effect_flags;
    uint32_t base_heal;
} catalog_item_definition;

/** Decoded ability record. */
typedef struct catalog_ability_definition
{
    uint32_t struct_id;
    uint32_t name_offset;
    int32_t start_var;
    int32_t end_var;
    uint32_t base_cooldown_ms;
    uint32_t requirements;
    uint32_t combat_style;
    uint32_t timer_source;
    uint32_t level_requirement;
    uint32_t adrenaline_requirement_raw;
    uint32_t definition_flags;
} catalog_ability_definition;

/** Computes the SHA-256 digest of size bytes. */
int catalog_sha256(const unsigned char *data, uint32_t size,
                   unsigned char digest[CATALOG_SHA256_BYTES]);

/**
 * Loads and validates a catalog file. Returns an enum rs3_result. A failed
 * load keeps the previous valid catalog and records an error message.
 */
int32_t catalog_load_file(item_catalog *catalog, const wchar_t *path);

/** Tries rs3_catalog.bin beside the module that contains this library. */
void catalog_load_default(item_catalog *catalog);

/** Releases the backing buffer. */
void catalog_free(item_catalog *catalog);

/** Finds an item by ID. Returns nonzero and fills definition when present. */
int catalog_find_item(const item_catalog *catalog, int32_t item_id,
                      catalog_item_definition *definition);

/** Decodes the ability record at index (below catalog->ability_count). */
void catalog_get_ability(const item_catalog *catalog, uint32_t index,
                         catalog_ability_definition *definition);

/** Copies a name, truncated on a UTF-8 boundary to fit CATALOG_NAME_CAPACITY. */
void catalog_copy_name(const item_catalog *catalog, uint32_t name_offset,
                       char output[CATALOG_NAME_CAPACITY]);

#endif /* RS3_CATALOG_H */
